class Solution {
public:
    int countDominantIndices(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        for (int i = 0; i + 1 < n; i++) {
            long long s = 0;
            for (int j = i + 1; j < n; j++) s += nums[j];
            if ((long long)nums[i] * (n - 1 - i) > s) ans++;
        }
        return ans;
    }
};

